$bestand=dirname(__DIR__).'/data/rekentabel.json';$standaard=['jaar'=>date('Y'),'inschrijfkosten'=>10,'jeugd_jaarbedrag'=>50,'senior_jaarbedrag'=>100,'jeugd_leeftijd_tot'=>15,'jeugd_jaarbedrag_volgend'=>'','senior_jaarbedrag_volgend'=>''];$data=array_merge($standaard,beheerEditorLeesJson($bestand,[]));$melding='';$type='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){$melding='Sessie verlopen. Ververs de pagina en probeer opnieuw.';$type='fout';}
 else{$jaar=trim((string)($_POST['jaar']??''));$ins=str_replace(',','.',trim((string)($_POST['inschrijfkosten']??'')));$jeugd=str_replace(',','.',trim((string)($_POST['jeugd_jaarbedrag']??'')));$senior=str_replace(',','.',trim((string)($_POST['senior_jaarbedrag']??'')));$leeftijd=trim((string)($_POST['jeugd_leeftijd_tot']??''));$jeugdVolgend=str_replace(',','.',trim((string)($_POST['jeugd_jaarbedrag_volgend']??'')));$seniorVolgend=str_replace(',','.',trim((string)($_POST['senior_jaarbedrag_volgend']??'')));
 if($jaar===''||!preg_match('/^\d{4}$/',$jaar)){$melding='Vul een geldig jaartal in (bijv. 2026).';$type='fout';}elseif(!is_numeric($ins)||(float)$ins<0){$melding='Inschrijfkosten moet een bedrag van 0 of hoger zijn.';$type='fout';}elseif(!is_numeric($jeugd)||(float)$jeugd<0){$melding='Jaarbedrag jeugd moet een bedrag van 0 of hoger zijn.';$type='fout';}elseif(!is_numeric($senior)||(float)$senior<0){$melding='Jaarbedrag senior moet een bedrag van 0 of hoger zijn.';$type='fout';}elseif(!ctype_digit($leeftijd)||(int)$leeftijd<1||(int)$leeftijd>99){$melding='Leeftijdsgrens jeugd moet een heel getal tussen 1 en 99 zijn.';$type='fout';}elseif($jeugdVolgend!==''&&(!is_numeric($jeugdVolgend)||(float)$jeugdVolgend<0)){$melding='Jaarbedrag jeugd volgend jaar moet leeg zijn of een bedrag van 0 of hoger.';$type='fout';}elseif($seniorVolgend!==''&&(!is_numeric($seniorVolgend)||(float)$seniorVolgend<0)){$melding='Jaarbedrag senior volgend jaar moet leeg zijn of een bedrag van 0 of hoger.';$type='fout';}else{$nieuw=['jaar'=>$jaar,'inschrijfkosten'=>(float)$ins,'jeugd_jaarbedrag'=>(float)round((float)$jeugd),'senior_jaarbedrag'=>(float)round((float)$senior),'jeugd_leeftijd_tot'=>(int)$leeftijd,'jeugd_jaarbedrag_volgend'=>$jeugdVolgend===''?'':(float)round((float)$jeugdVolgend),'senior_jaarbedrag_volgend'=>$seniorVolgend===''?'':(float)round((float)$seniorVolgend)];$slot=dataSlotOpen();try{$ok=beheerEditorSchrijfJson($bestand,$nieuw);}finally{dataSlotDicht($slot);}if($ok){$data=$nieuw;$melding='Rekentabel opgeslagen. De contributiecalculator gebruikt meteen deze bedragen.';$type='ok';$volgend=($jeugdVolgend===''&&$seniorVolgend==='')?'volgend jaar nog niet vastgesteld':'volgend jaar jeugd €'.($jeugdVolgend===''?'-':$jeugdVolgend).', senior €'.($seniorVolgend===''?'-':$seniorVolgend);schrijfLog($logBestand,$huidigeGebruiker,'rekentabel',"jaar $jaar, inschrijfkosten €$ins, jeugd €$jeugd, senior €$senior, $volgend");}else{$melding='Opslaan mislukt.';$type='fout';}}}
}
$jeugdTabel=rekentabelProRata((float)$data['jeugd_jaarbedrag']);$seniorTabel=rekentabelProRata((float)$data['senior_jaarbedrag']);
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Rekentabel beheren</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{background:#fff;border-bottom:1px solid #ddd8c0;padding:16px 24px}.topin,.wrap{max-width:1000px;margin:auto}.topin{display:flex;justify-content:space-between}.top a{color:#2d6260;text-decoration:none;font-weight:700}.wrap{padding:30px 24px 70px}.kaart{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.veld label{display:block;font-weight:700;font-size:12px;margin:0 0 5px}.veld input{width:100%;box-sizing:border-box;border:1px solid #cfcab7;border-radius:8px;padding:10px;font:inherit}.melding{padding:12px 14px;border-radius:9px;margin-bottom:18px}.ok{background:#e8f5ee;color:#205b38}.fout{background:#fdeceb;color:#8b2e27}.btn{background:#3a7a77;color:#fff;border:0;border-radius:9px;padding:11px 18px;font-weight:700;cursor:pointer}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #eee;text-align:left}.hint{color:#68705f}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><div class="topin"><a href="./">← Terug naar beheer</a><a href="../aanmelden.html" target="_blank" rel="noopener">Bekijk aanmelden ↗</a></div></div><main class="wrap"><h1>Rekentabel contributie</h1><?php if($melding!==''):?><div class="melding <?=beheerEditorEsc($type)?>"><?=beheerEditorEsc($melding)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=beheerEditorEsc($csrfToken)?>"><section class="kaart"><div class="grid"><div class="veld"><label>Jaar</label><input name="jaar" maxlength="4" inputmode="numeric" value="<?=beheerEditorEsc($data['jaar'])?>"></div><div class="veld"><label>Inschrijfkosten</label><input name="inschrijfkosten" inputmode="decimal" value="<?=beheerEditorEsc($data['inschrijfkosten'])?>"></div><div class="veld"><label>Jaarbedrag jeugd</label><input name="jeugd_jaarbedrag" inputmode="decimal" value="<?=beheerEditorEsc($data['jeugd_jaarbedrag'])?>"></div><div class="veld"><label>Jaarbedrag senior</label><input name="senior_jaarbedrag" inputmode="decimal" value="<?=beheerEditorEsc($data['senior_jaarbedrag'])?>"></div><div class="veld"><label>Jeugd t/m leeftijd</label><input name="jeugd_leeftijd_tot" inputmode="numeric" value="<?=beheerEditorEsc($data['jeugd_leeftijd_tot'])?>"></div></div></section><section class="kaart"><h2>Volgend jaar (optioneel)</h2><p class="hint">Leeg laten zolang de nieuwe contributie nog niet is vastgesteld.</p><div class="grid"><div class="veld"><label>Jeugd volgend jaar</label><input name="jeugd_jaarbedrag_volgend" inputmode="decimal" value="<?=beheerEditorEsc($data['jeugd_jaarbedrag_volgend'])?>"></div><div class="veld"><label>Senior volgend jaar</label><input name="senior_jaarbedrag_volgend" inputmode="decimal" value="<?=beheerEditorEsc($data['senior_jaarbedrag_volgend'])?>"></div></div></section><button class="btn" type="submit">Rekentabel opslaan</button></form><section class="kaart"><h2>Controle huidige pro-rata tabel</h2><table><thead><tr><th>Maand</th><th>Jeugd</th><th>Senior</th></tr></thead><tbody><?php $namen=[1=>'jan',2=>'feb',3=>'mrt',4=>'apr',5=>'mei',6=>'jun',7=>'jul',8=>'aug',9=>'sep',10=>'okt',11=>'nov',12=>'dec'];foreach($namen as $m=>$naam):?><tr><td><?=beheerEditorEsc($naam)?></td><td><?=$jeugdTabel[$m]===null?'—':'€'.beheerEditorEsc($jeugdTabel[$m])?></td><td><?=$seniorTabel[$m]===null?'—':'€'.beheerEditorEsc($seniorTabel[$m])?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
